alter table public.articles add column if not exists keywords text, add column if not exists discipline text, add column if not exists author_name text, add column if not exists affiliation text, add column if not exists coauthors text;
create policy articles_own_submit on public.articles for update to authenticated using (submitter_id=(select auth.uid()) and status='draft') with check (submitter_id=(select auth.uid()) and status in ('draft','submitted'));
create policy versions_own_insert on public.article_versions for insert to authenticated with check (version_number=1 and exists(select 1 from public.articles a where a.id=article_id and a.submitter_id=(select auth.uid()) and a.status='draft'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('manuscripts','manuscripts',false,15728640,array['application/pdf']) on conflict(id) do update set public=false,file_size_limit=15728640,allowed_mime_types=array['application/pdf'];
create policy manuscript_owner_upload on storage.objects for insert to authenticated with check (bucket_id='manuscripts' and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.articles a where a.id=((storage.foldername(name))[2])::uuid and a.submitter_id=(select auth.uid()) and a.status='draft') and storage.extension(name)='pdf');
create policy manuscript_owner_read on storage.objects for select to authenticated using (bucket_id='manuscripts' and (storage.foldername(name))[1]=(select auth.uid())::text);